INSERT INTO repo_subtopics (subtopic_id, name, subtopic_no, description, subtopic_sd_id, review_status, status, version) VALUES ('SUB_COURSE_001_M01_S01', 'Classes', '1', 'Classes refers to an object-oriented programming construct that defines the attributes/state and operations/behaviour shared by objects of the class. In Foundations & Linear Data Structures, the focus is on class definitions, objects/instances, attributes, methods, encapsulation, abstraction, constructors, visibility and implementation of abstract data types.', 'SSD_CLASSES', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_001_M01_S02', 'Stacks', '2', 'Stacks refers to a linear abstract data type in which insertion and deletion occur at one designated end, following last-in-first-out (LIFO) order. In Foundations & Linear Data Structures, the focus is on push, pop, peek/top, underflow/overflow conditions, array- and linked implementations, and time/space complexity.', 'SSD_STACKS', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_001_M02_S01', 'Queues', '1', 'Queues refers to a linear abstract data type in which insertion is performed at one end and deletion at the other, following first-in-first-out (FIFO) order. In Linear Data Structures, the focus is on enqueue, dequeue, front/rear operations, circular queues, array/linked implementations, and underflow/overflow conditions.', 'SSD_QUEUES', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_001_M02_S02', 'Linked Lists', '2', 'Linked Lists refers to a linked linear data structure consisting of nodes that contain data and one or more links to other nodes. In Linear Data Structures, the focus is on singly, doubly and circular lists; insertion/deletion; traversal; node references.', 'SSD_LINKED_LISTS', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_001_M03_S01', 'Binary Search Tree (BST)', '1', 'Binary Search Tree (BST) refers to a binary tree in which keys in the left subtree are ordered relative to the node key and keys in the right subtree are ordered in the opposite direction, according to the chosen ordering rule. In Trees & Graphs, the focus is on search, insertion, deletion, traversal, ordering invariant, height and best/average/worst-case complexity.', 'SSD_BST', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_001_M03_S02', 'AVL Trees', '2', 'AVL Trees refers to a self-balancing binary search tree in which the height difference between the left and right subtrees of every node is bounded by one. In Trees & Graphs, the focus is on balance factor, rotations, insertion/deletion rebalancing, search and height guarantees.', 'SSD_AVL_TREES', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_001_M04_S01', 'Quick/Merge sort', '1', 'Quick/Merge sort: Comparison-based sorting methods represented here by Quicksort and Mergesort, which organize elements into sorted order using divide-and-conquer strategies. In Sorting & Searching, the focus is on partitioning and recursive subproblems in Quicksort; splitting and merging in Mergesort; stability, in-place behaviour and time/space complexity.', 'SSD_QUICK_MERGE_SORT', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_001_M04_S02', 'Binary Search', '2', 'Binary Search refers to a search algorithm that repeatedly compares a target with the middle element of an ordered sequence and eliminates half of the remaining search interval. In Sorting & Searching, the focus is on sorted data requirement, iterative/recursive implementation, interval reduction and complexity.', 'SSD_BINARY_SEARCH', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_001_M05_S01', 'Collision resolution', '1', 'Collision resolution: Techniques used in hash tables to handle multiple keys that map to the same table location. In Hashing, the focus is on separate chaining, open addressing, probing strategies, load factor and clustering effects.', 'SSD_COLLISION_RESOLUTION', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_002_M01_S01', 'Truth tables', '1', 'Truth tables refers to a tabular method for evaluating the truth value of a propositional or logical expression for every possible assignment of its component propositions. In Propositional Logic, the focus is on logical connectives, compound propositions, equivalence, tautology, contradiction and satisfiability checks.', 'SSD_TRUTH_TABLES', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_002_M02_S01', 'Induction', '1', 'Induction refers to a proof method in which a statement is established for an initial case and then shown to hold for the next case assuming it holds for the current case. In Proof Techniques, the focus is on weak/ordinary induction, strong induction, base case, inductive hypothesis and inductive step.', 'SSD_INDUCTION', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_002_M03_S01', 'Equivalence relations', '1', 'Equivalence relations refers to a binary relation that is reflexive, symmetric and transitive, thereby partitioning a set into equivalence classes. In Set Theory & Relations, the focus is on relation properties, equivalence classes, partitions and representative elements.', 'SSD_EQUIVALENCE_RELATIONS', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_002_M04_S01', 'Pigeonhole principle', '1', 'Pigeonhole principle refers to a counting principle stating that placing more objects than containers into those containers forces at least one container to contain more than one object. In Combinatorics, the focus is on basic and generalized forms, counting arguments and existence proofs.', 'SSD_PIGEONHOLE_PRINCIPLE', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_002_M05_S01', 'Trees', '1', 'Trees refers to a connected acyclic graph used to represent hierarchical or recursive relationships. In Graph Theory, the focus is on rooted trees, parent/child relationships, degree, height, depth, traversal and common tree representations.', 'SSD_TREES', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_003_M01_S01', 'Entities, relationships & constraints', '1', 'Entities, relationships & constraints: Core components of conceptual database modelling in which entities represent distinguishable objects, relationships represent associations, and constraints specify valid states. In ER Modeling, the focus is on entity sets, attributes, relationship sets, cardinality/participation constraints, keys and integrity constraints.', 'SSD_ENTITIES_RELATIONSHIPS_CONSTRAINTS', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_003_M02_S01', 'Relational algebra', '1', 'Relational algebra refers to a formal procedural query language based on operations over relations, producing relations as results. In Relational Model, the focus is on selection, projection, union, difference, Cartesian product, joins, renaming and derived operations.', 'SSD_RELATIONAL_ALGEBRA', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_003_M03_S01', 'SQL queries', '1', 'SQL queries: Declarative statements used to define, retrieve, manipulate and control data in relational database systems. In SQL, the focus is on sELECT queries, filtering, joins, grouping, aggregation, subqueries and data modification statements.', 'SSD_SQL_QUERIES', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_003_M04_S01', 'Boyce-Codd Normal Form', '1', 'Boyce-Codd Normal Form refers to a relational normal form in which every determinant of a non-trivial functional dependency is a superkey. In Normalization, the focus is on functional dependencies, candidate keys, determinants, decomposition and lossless/dependency-preserving considerations.', 'SSD_BOYCE_CODD_NORMAL_FORM', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_003_M05_S01', 'Concurrency control', '1', 'Concurrency control: Database mechanisms that coordinate concurrent transactions so that their interleaved execution preserves required correctness properties. In Transaction Management, the focus is on serializability, locking, timestamps, isolation, conflicts, deadlock interaction and recovery considerations.', 'SSD_CONCURRENCY_CONTROL', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_004_M01_S01', 'Deadlocks', '1', 'Deadlocks refers to a state in which a set of processes or threads are permanently blocked because each waits for a resource or event held or controlled by another member of the set. In Processes, the focus is on necessary conditions, resource-allocation graphs, prevention, avoidance, detection and recovery.', 'SSD_DEADLOCKS', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_004_M02_S01', 'Thread synchronization', '1', 'Thread synchronization: Coordination mechanisms that control the ordering and mutual access of concurrent threads to shared state. In Threads & Synchronization, the focus is on critical sections, mutexes/locks, semaphores, monitors, condition variables, race conditions and atomicity.', 'SSD_THREAD_SYNCHRONIZATION', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_004_M03_S01', 'Scheduling algorithms', '1', 'Scheduling algorithms: Algorithms used by an operating system to select processes or threads for execution and allocate processor time. In CPU Scheduling, the focus is on fCFS, SJF/SRTF, priority, round-robin and multilevel scheduling; response, waiting and turnaround metrics.', 'SSD_SCHEDULING_ALGORITHMS', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_004_M04_S01', 'Paging and virtual memory', '1', 'Paging and virtual memory: Memory-management techniques that divide address spaces into pages and physical memory into frames, allowing virtual addresses to be mapped to physical locations. In Memory Management, the focus is on page tables, address translation, page faults, demand paging, replacement and working-set considerations.', 'SSD_PAGING_AND_VIRTUAL_MEMORY', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_004_M05_S01', 'File allocation and organization', '1', 'File allocation and organization: Methods by which an operating system organizes files and allocates storage blocks to represent their contents. In File Systems, the focus is on contiguous, linked and indexed allocation, directories, free-space management and access patterns.', 'SSD_FILE_ALLOCATION_AND_ORGANIZATION', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_005_M01_S01', 'Arithmetic Logic Unit (ALU)', '1', 'Arithmetic Logic Unit (ALU) refers to the arithmetic logic unit is a processor datapath component that performs arithmetic, logical and related bitwise operations on operands. In Digital Logic, the focus is on arithmetic operations, logical operations, flags/status outputs, operand width and datapath integration.', 'SSD_ALU', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_005_M02_S01', 'Reduced Instruction Set Computer / Complex Instruction Set Computer (RISC/CISC)', '1', 'RISC/CISC: Two broad instruction-set design approaches distinguished by how instruction complexity, encoding, addressing and implementation responsibilities are organized. In Instruction Set Architecture, the focus is on instruction complexity, instruction formats, addressing modes, register use, code density and implementation trade-offs.', 'SSD_RISC_CISC', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_005_M03_S01', 'Pipeline hazards', '1', 'Pipeline hazards: Conditions in a pipelined processor that prevent the next instruction from proceeding through the pipeline as scheduled. In Pipelining, the focus is on structural, data and control hazards; stalls, forwarding, scheduling and branch handling.', 'SSD_PIPELINE_HAZARDS', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_005_M04_S01', 'Caches and virtual memory', '1', 'Caches and virtual memory: Memory-hierarchy mechanisms that exploit locality: caches retain frequently used data near processors, while virtual memory maps virtual addresses to physical storage. In Memory Hierarchy, the focus is on cache levels, locality, mapping, replacement, write policies, TLBs and page translation.', 'SSD_CACHES_AND_VIRTUAL_MEMORY', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_005_M05_S01', 'I/O organization and interfaces', '1', 'I/O organization and interfaces: Processor and system mechanisms used to communicate with peripheral devices and external interfaces. In I/O Systems, the focus is on programmed I/O, interrupts, DMA, buses, device controllers and interface protocols.', 'SSD_I_O_ORGANIZATION_AND_INTERFACES', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_006_M01_S01', 'Merge sort', '1', 'Merge sort refers to a stable comparison-based sorting algorithm that recursively divides a sequence and merges sorted sub-sequences. In Divide & Conquer, the focus is on divide-and-conquer decomposition, merge operation, stability and auxiliary storage.', 'SSD_MERGE_SORT', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_006_M02_S01', 'Knapsack', '1', 'Knapsack refers to a family of optimization problems that selects items under a capacity constraint to maximize total value. In Dynamic Programming, the focus is on for 0/1 knapsack, each item is selected at most once; state formulation, recurrence, dynamic programming and capacity/value constraints.', 'SSD_KNAPSACK', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_006_M03_S01', 'Activity selection', '1', 'Activity selection refers to a scheduling problem that selects a maximum-size subset of mutually compatible activities given start and finish times. In Greedy Algorithms, the focus is on compatibility, earliest-finish-time greedy rule, selection sequence and proof of optimality.', 'SSD_ACTIVITY_SELECTION', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_006_M04_S01', 'Network flow', '1', 'Network flow refers to a graph-based optimization model in which flow is sent through directed edges subject to capacity constraints from a source toward a sink. In Graph Algorithms, the focus is on flow conservation, capacities, residual networks, augmenting paths, max-flow/min-cut and common algorithms.', 'SSD_NETWORK_FLOW', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_006_M05_S01', 'NP-complete problems', '1', 'NP-complete problems: Decision problems that are both in NP and NP-hard, meaning every problem in NP can be polynomial-time reduced to them. In NP-Completeness, the focus is on polynomial verification, polynomial-time reductions, NP-hardness and representative problems.', 'SSD_NP_COMPLETE_PROBLEMS', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_007_M01_S01', 'Process models', '1', 'Process models: Structured approaches for organizing software development activities, deliverables and control points across a development lifecycle. In Software Development Life Cycle, the focus is on waterfall, iterative/incremental, spiral, agile and hybrid lifecycle approaches; activities, feedback and change management.', 'SSD_PROCESS_MODELS', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_007_M02_S01', 'Continuous integration and delivery', '1', 'Continuous integration and delivery: Software engineering practices that automate frequent integration, verification and delivery of software changes through a controlled pipeline. In Agile & Scrum, the focus is on build automation, version control integration, automated tests, artifact management, deployment automation and release controls.', 'SSD_CONTINUOUS_INTEGRATION_AND_DELIVERY', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_007_M03_S01', 'Use cases and requirements specification', '1', 'Use cases and requirements specification: Techniques for eliciting, documenting and validating required system behaviour, qualities and constraints from stakeholder needs. In Requirements Engineering, the focus is on functional/non-functional requirements, actors, use cases, scenarios, acceptance criteria, traceability and validation.', 'SSD_USE_CASES_AND_REQUIREMENTS_SPECIFICATION', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_007_M04_S01', 'Design patterns', '1', 'Design patterns: Reusable, named design solutions to recurring software design problems within a stated context and set of trade-offs. In System Design, the focus is on creational, structural and behavioural patterns; participants, collaborations, consequences and applicability.', 'SSD_DESIGN_PATTERNS', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_007_M05_S01', 'Unit and integration testing', '1', 'Unit and integration testing: Testing practices that verify individual software units and their interactions with collaborating components. In Software Testing, the focus is on test cases, fixtures, mocks/stubs, unit boundaries, integration strategies, interfaces and defect isolation.', 'SSD_UNIT_AND_INTEGRATION_TESTING', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_008_M01_S01', 'Transmission media and signalling', '1', 'Transmission media and signalling: Physical means and signalling methods used to carry information across a communication channel. In Physical Layer, the focus is on copper, fibre and wireless media; bandwidth, attenuation, noise, modulation/encoding and transmission characteristics.', 'SSD_TRANSMISSION_MEDIA_AND_SIGNALLING', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_008_M02_S01', 'Framing and MAC', '1', 'Framing and MAC: Data-link mechanisms that delimit frames and control access to a shared or point-to-point communication medium. In Data Link Layer, the focus is on frame structure, error detection, MAC addressing, Ethernet, collision handling and medium-access methods.', 'SSD_FRAMING_AND_MAC', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_008_M03_S01', 'IP addressing and routing', '1', 'IP addressing and routing: Network-layer mechanisms for identifying interfaces or endpoints and selecting paths for forwarding packets between networks. In Network Layer, the focus is on iPv4/IPv6 addressing, subnetting, forwarding tables, routing principles and route selection.', 'SSD_IP_ADDRESSING_AND_ROUTING', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_008_M04_S01', 'Transmission Control Protocol / User Datagram Protocol (TCP/UDP)', '1', 'TCP/UDP: Transport-layer protocols represented by TCP, a connection-oriented reliable byte-stream protocol, and UDP, a connectionless datagram transport. In Transport Layer, the focus is on ports, multiplexing, TCP sequencing/acknowledgement/congestion control and UDP datagrams.', 'SSD_TCP_UDP', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_008_M05_S01', 'Hypertext Transfer Protocol (HTTP)', '1', 'Hypertext Transfer Protocol (HTTP) refers to an application-layer request/response protocol used for transferring web resources and related representations. In Application Layer, the focus is on methods, status codes, headers, message semantics, caching, persistent connections and HTTP over secure transports.', 'SSD_HTTP', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_009_M01_S01', 'Hooke''s Law', '1', 'Hooke''s Law: Within the linear elastic range of a material, stress is proportional to strain for the relevant loading mode. In Simple Stresses, the focus is on normal stress/strain relation, elastic modulus, proportional limit and applicability to linear elasticity.', 'SSD_HOOKE_S_LAW', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_009_M02_S01', 'Flexure formula', '1', 'Flexure formula refers to the beam flexure relation that connects bending stress to bending moment, cross-sectional geometry and distance from the neutral axis under stated beam assumptions. In Bending Moment, the focus is on σ = My/I, neutral axis, second moment of area, bending moment and elastic-beam assumptions.', 'SSD_FLEXURE_FORMULA', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_009_M03_S01', 'Bending stress distribution', '1', 'Bending stress distribution refers to the spatial variation of normal bending stress across a beam cross-section caused by an applied bending moment. In Bending Stresses, the focus is on linear stress distribution in elastic homogeneous sections, neutral axis, extreme fibres and section modulus.', 'SSD_BENDING_STRESS_DISTRIBUTION', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_009_M04_S01', 'Circular shafts', '1', 'Circular shafts: Cylindrical structural members designed to transmit torque and resist associated torsional stresses and deformation. In Torsion, the focus is on solid/hollow shafts, torque, polar moment of inertia, torsional shear stress, angle of twist and power transmission.', 'SSD_CIRCULAR_SHAFTS', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_009_M05_S01', 'Beam deflection methods', '1', 'Beam deflection methods: Analytical methods used to determine displacement and slope of beams under transverse loading. In Deflection, the focus is on double integration, singularity functions, moment-area, conjugate beam and related elastic methods.', 'SSD_BEAM_DEFLECTION_METHODS', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_010_M01_S01', 'Viscosity', '1', 'Viscosity refers to a measure of a fluid’s resistance to deformation and flow, arising from internal friction and relating shear stress to velocity gradient under Newtonian conditions. In Fluid Properties, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_VISCOSITY', 'Semantically_Audited', 'Active', '1.0') ON CONFLICT DO NOTHING;